function defaultRolePermissions(role){
role=String(role||"OPERADOR").toUpperCase();
const out={};permissionModules.forEach(([m])=>out[m]={read:false,write:false,delete:false});
if(role==="ADMIN"){permissionModules.forEach(([m])=>out[m]={read:true,write:true,delete:true});return out}
if(role==="GERENCIA"){
["dashboard","products","categories","banners","orders","requests","virtual","office"].forEach(m=>out[m]={read:true,write:true,delete:true});
out.users={read:true,write:false,delete:false};out.settings={read:true,write:false,delete:false};return out;
}
if(role==="LECTURA"){["dashboard","products","categories","banners","orders","requests","virtual","office"].forEach(m=>out[m]={read:true,write:false,delete:false});return out}
out.dashboard={read:true,write:false,delete:false};
["products","categories","orders","requests","virtual","office"].forEach(m=>out[m]={read:true,write:true,delete:false});
out.banners={read:true,write:false,delete:false};return out;
}
function renderPermissionGrid(perms){
const grid=$("#permissionGrid");if(!grid)return;
const p=perms||defaultRolePermissions($("#uRole")?.value);
grid.innerHTML=`<div class="permission-row permission-row-head"><strong>Módulo</strong><span>Ver</span><span>Editar</span><span>Eliminar</span></div>`+permissionModules.map(([m,label])=>`<div class="permission-row" data-perm-module="${m}"><strong>${label}</strong><label><input type="checkbox" data-action="read" ${p?.[m]?.read?'checked':''}></label><label><input type="checkbox" data-action="write" ${p?.[m]?.write?'checked':''}></label><label><input type="checkbox" data-action="delete" ${p?.[m]?.delete?'checked':''}></label></div>`).join("");
const admin=$("#uRole")?.value==="ADMIN";
if(admin)grid.querySelectorAll("input").forEach(x=>{x.checked=true;x.disabled=true});
grid.querySelectorAll("input").forEach(input=>input.addEventListener("change",()=>{
const row=input.closest(".permission-row");
if((input.dataset.action==="write"||input.dataset.action==="delete")&&input.checked){const read=row.querySelector('[data-action="read"]');if(read)read.checked=true}
}));
}
function readPermissionGrid(){
const out={};
$$("#permissionGrid .permission-row[data-perm-module]").forEach(row=>{
out[row.dataset.permModule]={
read:!!row.querySelector('[data-action="read"]')?.checked,
write:!!row.querySelector('[data-action="write"]')?.checked,
delete:!!row.querySelector('[data-action="delete"]')?.checked
};
});
return out;
}
function clearAdminUserForm(){
["uId","uName","uEmail","uUsername","uPassword"].forEach(id=>{if($("#"+id))$("#"+id).value=""});
$("#uRole").value="OPERADOR";$("#uActive").checked=true;renderPermissionGrid(defaultRolePermissions("OPERADOR"));
}
function renderUsers(){
if(!$("#adminUsersTable"))return;
if(!can("users","read")){$("#adminUsersTable").innerHTML="";return}
const term=($("#adminUserSearch")?.value||"").trim().toLowerCase(),role=$("#adminUserRoleFilter")?.value||"";
const rows=(data.users||[]).filter(u=>{
const hay=`${u.nombre||""} ${u.usuario||""} ${u.email||""}`.toLowerCase();
return(!term||hay.includes(term))&&(!role||String(u.rol||"").toUpperCase()===role);
});
$("#adminUsersTable").innerHTML=table(["Usuario","Rol","Estado","Último acceso","Permisos","Acciones"],rows.map(u=>{
const active=String(u.activo||"SI").toUpperCase()==="SI";
const perms=u.permisos||{};
const modules=permissionModules.filter(([m])=>perms?.[m]?.read).map(([,label])=>label);
const actionButtons=can("users","write")?`<button onclick="editAdminUser('${esc(u.id)}')"><i class="bi bi-pencil"></i> Editar</button><button class="${active?'danger':''}" onclick="toggleAdminUser('${esc(u.id)}',${active?'false':'true'},this)"><i class="bi bi-${active?'person-dash':'person-check'}"></i> ${active?'Desactivar':'Activar'}</button>`:"";
return `<tr><td><strong>${esc(u.nombre||u.usuario)}</strong><br><small>${esc(u.usuario||"")} · ${esc(u.email||"")}</small></td><td><span class="role-pill">${esc(String(u.rol||""))}</span></td><td><span class="status-pill ${active?'is-active':'is-inactive'}">${active?'ACTIVO':'INACTIVO'}</span></td><td>${esc(formatDate(u.ultimo_acceso)||"Nunca")}</td><td><small>${esc(modules.join(", ")||"Sin acceso")}</small></td><td><div class="row-actions">${actionButtons}</div></td></tr>`;
}).join(""));
}
