const payload={id:$("#uId").value,nombre:$("#uName").value.trim(),email:$("#uEmail").value.trim(),usuario:$("#uUsername").value.trim(),rol:$("#uRole").value,activo:$("#uActive").checked,password:$("#uPassword").value,permisos:readPermissionGrid()};
if(!payload.nombre||!payload.usuario)throw new Error("Completa nombre y usuario");
