/* R3.8.4 - Centro de notificaciones y sincronización automática */
const adminNotificationPollMs=15000;
let adminNotificationTimer=null,adminNotificationBusy=false,adminNotificationBaselineReady=false,adminNotificationKnownKeys=new Set();
function adminNotificationUserId(){const u=data.currentUser||{};return String(u.id||u.usuario||u.email||'anon').replace(/[^a-zA-Z0-9_.-]/g,'_')}
function adminNotificationSeenKey(){return `asServiciosAdminNotificationSeenV1:${adminNotificationUserId()}`}
function adminNotificationSeen(){try{return new Set(JSON.parse(localStorage.getItem(adminNotificationSeenKey())||'[]'))}catch(_){return new Set()}}
function saveAdminNotificationSeen(set){try{localStorage.setItem(adminNotificationSeenKey(),JSON.stringify([...set].slice(-600)))}catch(_){}}
function adminNotificationTime(v){if(!v)return 0;const s=String(v).trim(),d=new Date(s);if(!isNaN(d))return d.getTime();const m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);if(m)return new Date(+m[3],+m[2]-1,+m[1],+(m[4]||0),+(m[5]||0),+(m[6]||0)).getTime();return 0}
function adminNotificationItems(){
  const items=[];
  if(can('requests','read'))(data.requests||[]).forEach(r=>items.push({key:`request:${r.id}`,kind:'request',id:r.id,title:'Solicitud web',name:r.nombre||'Cliente',detail:r.detalle||r.tipo||'Nueva solicitud recibida',contact:r.telefono||r.email||'',date:r.fecha||'',state:String(r.estado||'NUEVA').toUpperCase(),isNewState:String(r.estado||'NUEVA').toUpperCase()==='NUEVA',view:'requests'}));
  if(can('virtual','read'))(data.virtualMessages||[]).forEach(r=>items.push({key:`virtual:${r.id}`,kind:'virtual',id:r.id,title:'AS Virtual',name:r.nombre||'Cliente',detail:r.mensaje||r.resumen||'Nuevo mensaje recibido',contact:r.contacto||'',date:r.fecha||'',state:String(r.estado||'NUEVO').toUpperCase(),isNewState:String(r.estado||'NUEVO').toUpperCase()==='NUEVO',view:'virtual'}));
  return items.sort((a,b)=>adminNotificationTime(b.date)-adminNotificationTime(a.date)).slice(0,80)
}
function adminNotificationUnread(items=adminNotificationItems()){const seen=adminNotificationSeen();return items.filter(x=>x.isNewState&&!seen.has(x.key))}
function renderAdminNotifications({detectNew=false,previousKeys=null}={}){
  const items=adminNotificationItems(),seen=adminNotificationSeen(),unread=adminNotificationUnread(items),count=$('#adminNotificationCount'),list=$('#adminNotificationList'),bell=$('#adminNotificationBell');
  if(count){count.textContent=unread.length>99?'99+':String(unread.length);count.classList.toggle('hidden',unread.length===0)}
  if(bell)bell.classList.toggle('has-unread',unread.length>0);
  if(list)list.innerHTML=items.length?items.map(x=>`<button type="button" class="admin-notification-item ${x.kind==='virtual'?'is-virtual':''} ${x.isNewState&&!seen.has(x.key)?'is-unread':''}" onclick="openAdminNotification('${esc(x.key)}')"><span class="notification-item-icon"><i class="bi bi-${x.kind==='virtual'?'robot':'clipboard2-plus'}"></i></span><span class="notification-item-copy"><strong>${esc(x.name)} · ${esc(x.title)}</strong><span>${esc(x.detail)}</span><small>${esc(formatDate(x.date)||x.contact||x.state)}</small></span>${x.isNewState&&!seen.has(x.key)?'<span class="notification-unread-dot"></span>':''}</button>`).join(''):`<div class="notification-empty"><i class="bi bi-bell-slash"></i><strong>Sin notificaciones</strong><span>Las nuevas solicitudes y mensajes de AS Virtual aparecerán aquí automáticamente.</span></div>`;
  if(detectNew&&previousKeys){items.filter(x=>x.isNewState&&!previousKeys.has(x.key)).slice(0,4).reverse().forEach(showAdminNotificationPopup)}
  adminNotificationKnownKeys=new Set(items.map(x=>x.key));
  adminNotificationBaselineReady=true;
}
function markAdminNotificationRead(key){const seen=adminNotificationSeen();seen.add(key);saveAdminNotificationSeen(seen);renderAdminNotifications()}
window.openAdminNotification=key=>{const item=adminNotificationItems().find(x=>x.key===key);if(!item)return;markAdminNotificationRead(key);$('#adminNotificationPanel')?.classList.remove('open');$('#adminNotificationBell')?.classList.remove('is-open');$('#adminNotificationBell')?.setAttribute('aria-expanded','false');switchAdminView(item.view)};
function markAllAdminNotifications(){const seen=adminNotificationSeen();adminNotificationItems().filter(x=>x.isNewState).forEach(x=>seen.add(x.key));saveAdminNotificationSeen(seen);renderAdminNotifications();toast('Notificaciones marcadas como leídas','success')}
function dismissAdminNotificationPopup(el){if(!el)return;el.style.opacity='0';el.style.transform='translateY(-8px)';setTimeout(()=>el.remove(),180)}
window.dismissAdminNotificationPopup=dismissAdminNotificationPopup;
function showAdminNotificationPopup(item){const stack=$('#adminNotificationPopups');if(!stack)return;const card=document.createElement('article');card.className=`admin-notification-popup ${item.kind==='virtual'?'is-virtual':''}`;card.innerHTML=`<span class="notification-popup-icon"><i class="bi bi-${item.kind==='virtual'?'robot':'bell-fill'}"></i></span><span class="notification-popup-copy"><small>${item.kind==='virtual'?'NUEVO MENSAJE':'NUEVA SOLICITUD'}</small><strong>${esc(item.name)}</strong><span>${esc(item.detail)}</span></span><span class="notification-popup-actions"><button type="button" class="popup-view">Ver</button><button type="button" class="popup-close" aria-label="Cerrar"><i class="bi bi-x-lg"></i></button></span>`;stack.prepend(card);const bell=$('#adminNotificationBell');bell?.classList.remove('has-new');void bell?.offsetWidth;bell?.classList.add('has-new');card.querySelector('.popup-view')?.addEventListener('click',()=>{openAdminNotification(item.key);dismissAdminNotificationPopup(card)});card.querySelector('.popup-close')?.addEventListener('click',()=>dismissAdminNotificationPopup(card));setTimeout(()=>dismissAdminNotificationPopup(card),9000)}
function updateAdminNotificationSyncText(){const el=$('#adminNotificationSyncText');if(el)el.textContent=`Última sincronización ${new Date().toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`}
function renderRealtimeAdminSections(){
  if($('#kpiRequests'))$('#kpiRequests').textContent=(data.requests||[]).filter(x=>String(x.estado).toUpperCase()==='NUEVA').length;
  try{renderOrders();renderRequests();renderVirtual();renderQuotes()}catch(e){console.warn('Render realtime parcial',e)}
}
async function syncAdminNotifications({manual=false}={}){
  if(adminNotificationBusy||!token||!data.currentUser)return;
  adminNotificationBusy=true;const btn=$('#adminNotificationSyncNow');btn?.classList.add('is-syncing');const previous=new Set(adminNotificationKnownKeys.size?adminNotificationKnownKeys:adminNotificationItems().map(x=>x.key));
  try{
    const r=await AleAPI.get('adminBootstrap',{__token:token});
    data={products:[],categories:[],banners:[],orders:[],requests:[],virtualMessages:[],quotes:[],users:[],config:{},whatsappCloud:{configured:false},permissions:{},currentUser:data.currentUser,...r};
    data.virtualMessages=Array.isArray(data.virtualMessages)?data.virtualMessages:[];data.quotes=Array.isArray(data.quotes)?data.quotes:[];data.users=Array.isArray(data.users)?data.users:[];
    renderRealtimeAdminSections();applyCurrentUser();renderAdminNotifications({detectNew:adminNotificationBaselineReady,previousKeys:previous});updateAdminNotificationSyncText();setAdminConnection('online','Conectado');
    if(manual)toast('Sincronización completada','success');
  }catch(e){console.error(e);if(isAuthError(e)){stopAdminNotificationSync();saveSession('');showLogin(authMessageFromError(e));}else{setAdminConnection('offline','Sin conexión');if(manual)toast('No fue posible sincronizar','error',String(e?.message||e))}}
  finally{adminNotificationBusy=false;btn?.classList.remove('is-syncing')}
}
function startAdminNotificationSync(){if(adminNotificationTimer)clearInterval(adminNotificationTimer);if(!token||!data.currentUser)return;renderAdminNotifications();updateAdminNotificationSyncText();adminNotificationTimer=setInterval(()=>syncAdminNotifications(),adminNotificationPollMs)}
function stopAdminNotificationSync(){if(adminNotificationTimer){clearInterval(adminNotificationTimer);adminNotificationTimer=null}adminNotificationBaselineReady=false;adminNotificationKnownKeys=new Set()}
$('#adminNotificationBell')?.addEventListener('click',e=>{e.stopPropagation();const panel=$('#adminNotificationPanel'),open=!panel?.classList.contains('open');panel?.classList.toggle('open',open);panel?.setAttribute('aria-hidden',open?'false':'true');e.currentTarget.classList.toggle('is-open',open);e.currentTarget.setAttribute('aria-expanded',open?'true':'false');if(open)renderAdminNotifications()});
$('#adminNotificationPanel')?.addEventListener('click',e=>e.stopPropagation());document.addEventListener('click',()=>{$('#adminNotificationPanel')?.classList.remove('open');$('#adminNotificationBell')?.classList.remove('is-open');$('#adminNotificationBell')?.setAttribute('aria-expanded','false')});
$('#adminNotificationMarkAll')?.addEventListener('click',markAllAdminNotifications);$('#adminNotificationSyncNow')?.addEventListener('click',()=>syncAdminNotifications({manual:true}));
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&token&&data.currentUser)syncAdminNotifications()});
setInterval(()=>{if(token&&data.currentUser&&!adminNotificationTimer)startAdminNotificationSync();if((!token||!data.currentUser)&&adminNotificationTimer)stopAdminNotificationSync()},1200);
